//! /guides — the guides wiki vault.
//!
//! The guides are a portable markdown vault at `docs/guides/**/*.md`
//! (frontmatter: `title`, `kind`, optional `mode` / `category`),
//! rendered by the in-tree `editor::Editor` in its read-only mode with
//! Obsidian-style live preview, and navigated through `[[wikilinks]]`,
//! a note explorer, and the Task knowledge graph
//! (`view_knowledge_graph`).
//!
//! Loading:
//! - release / native: the vault is embedded at build time
//!   (`embedded::VAULT`, generated by build.rs);
//! - dev on wasm (`debug_assertions`): the same files are fetched over
//!   HTTP from the dx dev server (bundled as the `assets/guides`
//!   folder asset, a symlink to `docs/guides`), so editing a note
//!   updates the site without a rebuild. The embedded copy is the file
//!   LIST either way — adding a note needs a rebuild, editing doesn't.

use std::collections::BTreeMap;
use std::rc::Rc;

use dioxus::prelude::*;
use editor::editor_view::DecorationSource;
use editor::{Editor, EditorState, markdown};
use architect_ui::lucide_dioxus::{FileText, Folder, Keyboard, Lightbulb, Wrench};
use architect_ui::prelude::*;
use view_knowledge_graph::{KnowledgeGraphView, WikiFile, build_wiki_graph};

use crate::Route;
use crate::components::colors::category_color;
use crate::components::input_tutorial::embedded::{MEDIA_ASSETS, VAULT};
use crate::components::modes::find_mode;

// ---------------------------------------------------------------------------
// Vault model + loading
// ---------------------------------------------------------------------------

/// One vault note: path is vault-relative (`reaper/transport.md`).
#[derive(Clone, PartialEq)]
pub struct VaultNote {
    pub path: String,
    pub content: String,
}

impl VaultNote {
    /// File stem — the wikilink / graph-node id (`transport`).
    pub fn stem(&self) -> &str {
        let file = self.path.rsplit('/').next().unwrap_or(&self.path);
        file.strip_suffix(".md").unwrap_or(file)
    }

    /// Display title: frontmatter `title:`, else de-dashed stem.
    pub fn title(&self) -> String {
        fm_field(&self.content, "title")
            .unwrap_or_else(|| self.stem().replace('-', " "))
    }
}

/// Read a scalar `key: value` line from the note's YAML frontmatter.
pub fn fm_field(content: &str, key: &str) -> Option<String> {
    let fm = view_knowledge_graph::parse::frontmatter(content);
    for line in fm.lines() {
        if let Some(rest) = line.trim_end().strip_prefix(key) {
            if let Some(val) = rest.strip_prefix(':') {
                let val = val
                    .trim()
                    .trim_start_matches(['"', '\''])
                    .trim_end_matches(['"', '\'']);
                if !val.is_empty() {
                    return Some(val.to_string());
                }
            }
        }
    }
    None
}

/// The whole embedded vault (also the dev-mode file list).
pub fn embedded_vault() -> Vec<VaultNote> {
    VAULT
        .iter()
        .map(|n| VaultNote {
            path: n.id.to_string(),
            content: n.styx.to_string(),
        })
        .collect()
}

/// Load the vault. Release/native: the embedded copy. Dev on wasm:
/// fetch each note from the dx dev server through its per-file
/// `asset!` URL (see build.rs `VAULT_ASSETS`) — dx hot-reloads
/// single-file assets in place (same served URL, no rebuild), so note
/// edits show up on the next load (per-file fallback to the embedded
/// copy).
pub async fn load_vault() -> Vec<VaultNote> {
    #[cfg(all(target_arch = "wasm32", debug_assertions))]
    {
        use crate::components::input_tutorial::embedded::VAULT_ASSETS;
        let mut notes = embedded_vault();
        for note in &mut notes {
            let Some((_, asset)) = VAULT_ASSETS.iter().find(|(p, _)| *p == note.path) else {
                continue;
            };
            let url = format!("{asset}?t={}", js_sys::Date::now() as u64);
            if let Some(text) = fetch_text(&url).await {
                note.content = text;
            }
        }
        notes
    }
    #[cfg(not(all(target_arch = "wasm32", debug_assertions)))]
    {
        embedded_vault()
    }
}

#[cfg(all(target_arch = "wasm32", debug_assertions))]
async fn fetch_text(url: &str) -> Option<String> {
    use wasm_bindgen::JsCast;
    use wasm_bindgen_futures::JsFuture;
    let win = web_sys::window()?;
    let resp = JsFuture::from(win.fetch_with_str(url)).await.ok()?;
    let resp: web_sys::Response = resp.dyn_into().ok()?;
    if !resp.ok() {
        return None;
    }
    // The dx dev server SPA-fallbacks unknown paths to index.html —
    // treat an HTML payload as a miss so we keep the embedded copy.
    let text = JsFuture::from(resp.text().ok()?).await.ok()?;
    let text = text.as_string()?;
    (!text.trim_start().starts_with("<!DOCTYPE")).then_some(text)
}

// ---------------------------------------------------------------------------
// Wikilink resolution (mirror of view_knowledge_graph::parse::resolve_target)
// ---------------------------------------------------------------------------

/// Resolve a wikilink target (`Transport`, `Input System`,
/// `transport#Rolling`, `reaper|REAPER Guide`) to a note. Matches the
/// file stem case-insensitively with whitespace→dash normalization,
/// falling back to the frontmatter title.
pub fn resolve_note<'a>(notes: &'a [VaultNote], target: &str) -> Option<&'a VaultNote> {
    let page = target.split(['#', '|']).next().unwrap_or(target).trim();
    if page.is_empty() {
        return None;
    }
    let norm = page.to_ascii_lowercase().replace(char::is_whitespace, "-");
    notes
        .iter()
        .find(|n| n.stem().to_ascii_lowercase() == norm)
        .or_else(|| {
            notes.iter().find(|n| {
                n.title()
                    .to_ascii_lowercase()
                    .replace(char::is_whitespace, "-")
                    == norm
            })
        })
}

/// Resolve URL segments (`["reaper", "transport"]`) to a note path:
/// `<joined>.md`, then the Obsidian folder-note `<joined>/<last>.md`;
/// empty segments land on the vault index `guides.md`.
pub fn resolve_route<'a>(notes: &'a [VaultNote], segs: &[String]) -> Option<&'a VaultNote> {
    let joined = segs.join("/");
    if joined.is_empty() {
        return notes.iter().find(|n| n.path == "guides.md");
    }
    let flat = format!("{joined}.md");
    let folder = format!("{joined}/{}.md", segs.last().map(String::as_str).unwrap_or(""));
    notes
        .iter()
        .find(|n| n.path.eq_ignore_ascii_case(&flat))
        .or_else(|| notes.iter().find(|n| n.path.eq_ignore_ascii_case(&folder)))
}

/// Route for a note path — folder notes (`reaper/reaper.md`) collapse
/// to their folder URL (`/guides/reaper`), the vault index to /guides.
pub fn note_route(path: &str) -> Route {
    let no_ext = path.strip_suffix(".md").unwrap_or(path);
    let mut segs: Vec<String> = no_ext.split('/').map(str::to_string).collect();
    if segs.len() >= 2 && segs[segs.len() - 1] == segs[segs.len() - 2] {
        segs.pop();
    }
    if segs.as_slice() == ["guides"] {
        return Route::GuidesPage {};
    }
    Route::GuideNotePage { path: segs }
}

// ---------------------------------------------------------------------------
// VaultLookup for the editor's live-preview pass
// ---------------------------------------------------------------------------

/// Wikilink/embed resolution for the editor decorations: resolved
/// links render purple instead of red, `![[embeds]]` get previews.
struct SiteVaultIndex {
    notes: Vec<VaultNote>,
}

impl SiteVaultIndex {
    fn body_preview(content: &str) -> String {
        body_without_frontmatter(content)
            .trim_start()
            .chars()
            .take(280)
            .collect()
    }
}

/// The note body with its yaml frontmatter block stripped — the
/// metadata renders as chips, not as a properties panel.
pub fn body_without_frontmatter(content: &str) -> &str {
    if view_knowledge_graph::parse::frontmatter(content).is_empty() {
        return content;
    }
    content
        .strip_prefix("---\n")
        .and_then(|r| r.find("\n---").map(|i| r[i + 4..].trim_start_matches('\n')))
        .unwrap_or(content)
}

// ---------------------------------------------------------------------------
// Guide screencast media (`gif` fences → embedded <img>/<video>)
// ---------------------------------------------------------------------------

/// The served URL for a screencast, by its logical name (the eventual
/// media filename stem, e.g. `transport-play`). Falls back to the
/// generic animated placeholder until a real recording is dropped into
/// `assets/guides-media/` under that stem. See `build.rs` `MEDIA_ASSETS`.
fn media_url(name: &str) -> Option<String> {
    let by = |stem: &str| MEDIA_ASSETS.iter().find(|(s, _)| *s == stem);
    by(name.trim())
        .or_else(|| by("_placeholder"))
        .map(|(_, asset)| asset.to_string())
}

/// Resolved media for a screencast name: `(url, is_video)`. Video
/// extensions render as a `<video>`, everything else as an `<img>`.
fn media_render(name: &str) -> Option<(String, bool)> {
    let url = media_url(name)?;
    let ext = url.rsplit('.').next().map(str::to_ascii_lowercase);
    let is_video = matches!(ext.as_deref(), Some("mp4" | "webm" | "mov" | "ogv"));
    Some((url, is_video))
}

/// One piece of a rendered note: either a run of markdown or a
/// screencast block (16:9 media beside a notes column). The vault view
/// renders each `Md` run in its own read-only editor and each `Cast` as
/// a native side-by-side block. `media_right` puts the media on the
/// right (text left) instead of the default media-left.
#[derive(Clone, PartialEq)]
pub enum Segment {
    Md(String),
    Cast {
        name: String,
        side_md: String,
        media_right: bool,
    },
}

/// Split a note body into markdown runs and screencast blocks. A
/// `` ```gif `` fence becomes a [`Segment::Cast`]:
///
/// The example is fenced with four backticks so the three-backtick
/// fence inside it doesn't close it early.
///
/// ````text
/// ```gif
/// transport-play                 ← media name (future filename stem)
/// Space plays and stops.         ← caption / notes column (markdown:
/// - Cursor returns to the start    bullets, **bold**, [[links]], and
/// - Great for repeated takes       `kbd:@` refs all render)
/// ```
/// ````
///
/// The info string picks the side: `` ```gif `` (or `` ```gif left ``)
/// puts the media on the left, `` ```gif right `` puts it on the right
/// (text left).
/// The first non-empty body line is the media NAME; everything after is
/// the side-column markdown. Keeping the source as a fence — not a raw
/// `![[…]]` — is deliberate: the vault's `[[wikilink]]` resolver and
/// knowledge graph must never see media embeds as note links.
pub fn parse_note_segments(body: &str) -> Vec<Segment> {
    let mut segs: Vec<Segment> = Vec::new();
    let mut md = String::new();
    let flush = |md: &mut String, segs: &mut Vec<Segment>| {
        if !md.trim().is_empty() {
            segs.push(Segment::Md(std::mem::take(md)));
        } else {
            md.clear();
        }
    };
    let mut lines = body.lines().peekable();
    while let Some(line) = lines.next() {
        let t = line.trim_start();
        // A `gif` fence, optionally with a `left` / `right` side flag.
        let (is_gif, media_right) = match t.strip_prefix("```gif") {
            Some(rest) => match rest.trim() {
                "" | "left" => (true, false),
                "right" => (true, true),
                _ => (false, false),
            },
            None => (false, false),
        };
        if !is_gif {
            md.push_str(line);
            md.push('\n');
            continue;
        }
        flush(&mut md, &mut segs);
        // Consume the fence body up to the closing ```.
        let mut inner: Vec<&str> = Vec::new();
        for l in lines.by_ref() {
            if l.trim_start().starts_with("```") {
                break;
            }
            inner.push(l);
        }
        // First non-empty line is the media name; the rest is the side
        // column markdown.
        let name_idx = inner.iter().position(|l| !l.trim().is_empty());
        let Some(i) = name_idx else { continue };
        let name = inner[i].trim().to_string();
        let side_md = inner[i + 1..].join("\n").trim().to_string();
        segs.push(Segment::Cast {
            name,
            side_md,
            media_right,
        });
    }
    flush(&mut md, &mut segs);
    segs
}

/// `kbd:@action` resolver: action id → the keys currently bound to it
/// in the embedded fasttrackstudio profile (bindings + which-key leaf
/// sequences), plus the shared mode/workflow layers.
pub(crate) struct SiteKbdIndex(std::collections::HashMap<String, String>);

impl SiteKbdIndex {
    pub(crate) fn build() -> Self {
        use crate::components::input_tutorial::embedded::PROFILES;

        fn walk_leaves(
            prefix: &str,
            entries: &[input_config_proto::WhichKeyEntryDef],
            map: &mut std::collections::HashMap<String, String>,
        ) {
            for e in entries {
                let seq = format!("{prefix} {}", e.key);
                if let Some(action) = &e.action {
                    map.entry(action.clone()).or_insert_with(|| seq.clone());
                }
                if let Some(children) = &e.children {
                    walk_leaves(&seq, children, map);
                }
            }
        }

        let mut map = std::collections::HashMap::new();
        if let Some(profile) = PROFILES.iter().find(|p| p.id == "fasttrackstudio") {
            for s in profile.sections {
                let config: input_config_proto::SectionConfig = match facet_styx::from_str(s.styx)
                {
                    Ok(c) => c,
                    Err(_) => continue,
                };
                for b in config.bindings() {
                    map.entry(b.action.clone()).or_insert_with(|| b.keys.clone());
                }
                for tree in config.which_key() {
                    walk_leaves(&tree.prefix, &tree.entries, &mut map);
                }
            }
        }
        // Mode/workflow layers, so notes about modal bindings
        // (take-ranking etc.) resolve too.
        for m in crate::components::modes::load_modes() {
            for b in &m.bindings {
                map.entry(b.action.clone()).or_insert_with(|| b.keys.clone());
            }
        }
        Self(map)
    }
}

impl markdown::KbdLookup for SiteKbdIndex {
    fn keys_for_action(&self, action: &str) -> Option<String> {
        self.0.get(action).cloned()
    }
}

impl markdown::VaultLookup for SiteVaultIndex {
    fn lookup_block(&self, _uuid: &str) -> Option<markdown::VaultBlockHit> {
        None
    }

    fn lookup_page(&self, name: &str) -> Option<markdown::VaultPageHit> {
        resolve_note(&self.notes, name).map(|n| markdown::VaultPageHit {
            preview: Self::body_preview(&n.content),
        })
    }

    fn lookup_section(&self, page: &str, heading: &str) -> Option<String> {
        let note = resolve_note(&self.notes, page)?;
        let mut out: Vec<&str> = Vec::new();
        let mut level = 0usize;
        for line in note.content.lines() {
            let hashes = line.bytes().take_while(|b| *b == b'#').count();
            let is_heading = hashes > 0 && line[hashes..].starts_with(' ');
            if level == 0 {
                if is_heading && line[hashes..].trim() == heading {
                    level = hashes;
                    out.push(line);
                }
            } else {
                if is_heading && hashes <= level {
                    break;
                }
                out.push(line);
            }
        }
        (!out.is_empty()).then(|| out.join("\n"))
    }

    fn lookup_block_short(&self, _page: &str, _short_id: &str) -> Option<String> {
        None
    }
}

// ---------------------------------------------------------------------------
// Frontmatter chips
// ---------------------------------------------------------------------------

fn kind_meta(kind: &str) -> (&'static str, Element) {
    match kind {
        "input" => ("#38bdf8", rsx! { Keyboard { class: "w-3.5 h-3.5" } }),
        "setup" => ("#10b981", rsx! { Wrench { class: "w-3.5 h-3.5" } }),
        _ => ("#a78bfa", rsx! { Lightbulb { class: "w-3.5 h-3.5" } }),
    }
}

/// Kind / mode / category chips derived from a note's frontmatter.
#[component]
fn NoteChips(content: String) -> Element {
    let kind = fm_field(&content, "kind");
    let mode = fm_field(&content, "mode");
    let category = fm_field(&content, "category");

    rsx! {
        div { class: "flex flex-wrap items-center gap-2",
            if let Some(k) = kind {
                {
                    let (color, icon) = kind_meta(&k);
                    rsx! {
                        span {
                            class: "inline-flex items-center gap-1.5 text-[0.65rem] px-2 py-0.5 rounded-full font-medium uppercase tracking-wider",
                            style: "color: {color}; background-color: {color}1a; border: 1px solid {color}40;",
                            {icon}
                            "{k}"
                        }
                    }
                }
            }
            if let Some(m) = mode {
                {
                    let color = category_color(&m);
                    let name = find_mode(&m).map(|md| md.name).unwrap_or_else(|| m.clone());
                    rsx! {
                        span {
                            class: "inline-flex items-center gap-1.5 text-[0.65rem] px-2 py-0.5 rounded-full font-medium",
                            style: "color: {color}; background-color: {color}1a; border: 1px solid {color}40;",
                            title: "Activate the {name} mode workflow to use these bindings",
                            span { class: "inline-block w-1.5 h-1.5 rounded-full", style: "background-color: {color};" }
                            "Mode: {name}"
                        }
                    }
                }
            }
            if let Some(c) = category {
                {
                    let color = category_color(&c);
                    let cat = c.clone();
                    rsx! {
                        Link {
                            to: Route::InputPage { category: cat },
                            class: "inline-flex items-center gap-1.5 text-[0.65rem] px-2 py-0.5 rounded-full font-medium hover:brightness-125 transition-all",
                            style: "color: {color}; background-color: {color}1a; border: 1px solid {color}40;",
                            span { class: "inline-block w-1.5 h-1.5 rounded-full", style: "background-color: {color};" }
                            "All {c} shortcuts \u{2192}"
                        }
                    }
                }
            }
        }
    }
}

