/// Site-theme overrides so the editor blends into the page (the
/// bundled editor.css targets a standalone card layout).
const VAULT_STYLE: &str = "
.guides-vault .editor-root { background: transparent; border: none; padding: 0; min-height: 0; }
.guides-vault .editor-frame { background: transparent; border: none; box-shadow: none; padding: 0; }
/* Reading measure for the read-only doc view — roomier than the
   editable 14px/1.6 default, which stays untouched for Task/editing
   contexts. */
.guides-vault .editor-root { font-size: 16px; line-height: 1.7; }
/* Screencast block: 16:9 media on the left, notes column on the right
   (see ScreencastBlock). The frame is a fixed 16:9 box; the notes
   column reuses the reading editor at a slightly smaller measure. */
.guides-vault .cast-frame {
    display: block;
    width: 100%;
    aspect-ratio: 16 / 9;
    object-fit: cover;
    border: 1px solid rgba(120, 140, 180, 0.22);
    border-radius: 10px;
    box-shadow: 0 8px 30px -12px rgba(0, 0, 0, 0.6);
    background: rgba(20, 24, 33, 0.5);
}
.guides-vault .cast-notes .editor-root { font-size: 0.95rem; line-height: 1.62; }
";

/// `/guides` and `/guides/:..path` — the vault view: note explorer,
/// the note in the read-only editor, and the knowledge graph.
#[component]
pub fn GuidesVault(#[props(default)] path: Vec<String>) -> Element {
    // Load (and in dev re-fetch) the vault whenever the route path
    // changes — that's what makes markdown edits show up on the next
    // navigation or reload without a rebuild.
    let route_key = path.join("/");
    let notes_res = use_resource(use_reactive!(|(route_key,)| async move {
        let _ = route_key;
        load_vault().await
    }));
    let notes: Vec<VaultNote> = notes_res.read().clone().unwrap_or_else(embedded_vault);

    let current = resolve_route(&notes, &path).cloned();

    // The note body, split into markdown runs and screencast blocks
    // (each rendered separately below). The frontmatter is stripped —
    // its metadata renders as chips above the note, not as a properties
    // panel.
    let segments: Vec<Segment> = current
        .as_ref()
        .map(|n| parse_note_segments(body_without_frontmatter(&n.content)))
        .unwrap_or_default();

    // Vault-aware live-preview decorations. The source captures the
    // signal (stable Rc identity across renders); the index inside is
    // swapped whenever the vault loads. The kbd resolver (for
    // `kbd:@action` shortcut refs) is static — built once from the
    // embedded profile + mode layers.
    let mut lookup = use_signal(|| None::<Rc<SiteVaultIndex>>);
    {
        let notes = notes.clone();
        use_effect(use_reactive!(|(notes,)| {
            lookup.set(Some(Rc::new(SiteVaultIndex { notes })));
        }));
    }
    let kbd_index = use_hook(|| Rc::new(SiteKbdIndex::build()));
    let decorations = use_hook(move || {
        DecorationSource::new(move |s: &EditorState| {
            let l = lookup.read();
            let vault_ref = l.as_ref().map(|rc| rc.as_ref() as &dyn markdown::VaultLookup);
            markdown::live_preview_with_lookups(
                s,
                vault_ref,
                Some(kbd_index.as_ref() as &dyn markdown::KbdLookup),
            )
        })
    });

    // Wikilink click → resolve → route. (http links are opened by the
    // editor itself; ignore them here.)
    let notes_for_links = notes.clone();
    let on_link_click = use_callback(move |href: String| {
        if href.contains("://") {
            return;
        }
        if let Some(note) = resolve_note(&notes_for_links, &href) {
            navigator().push(note_route(&note.path));
        }
    });

    // Knowledge graph of the whole vault.
    let graph_files: Vec<WikiFile> = notes
        .iter()
        .map(|n| WikiFile {
            name: n
                .path
                .rsplit('/')
                .next()
                .unwrap_or(&n.path)
                .to_string(),
            path: n.path.clone(),
            content: n.content.clone(),
        })
        .collect();
    let graph = build_wiki_graph(&graph_files);
    let notes_for_graph = notes.clone();
    let on_node_click = move |id: String| {
        if let Some(note) = resolve_note(&notes_for_graph, &id) {
            navigator().push(note_route(&note.path));
        }
    };
    let current_stem = current.as_ref().map(|n| n.stem().to_string());

    let current_path = current.as_ref().map(|n| n.path.clone()).unwrap_or_default();
    let title = current.as_ref().map(VaultNote::title).unwrap_or_default();

    rsx! {
        document::Link { rel: "stylesheet", href: editor::EDITOR_STYLE }
        document::Style { {VAULT_STYLE} }

        // Full-bleed reading canvas (no centered max-w cap): the note
        // sits in a wide flex-1 middle, the explorer hugs the left edge,
        // and the connections graph is pushed out to the far right edge —
        // out of the note's way, in what used to be the container's right
        // margin. The note keeps its comfortable prose measure, now with
        // much more room around it.
        div { class: "guides-vault w-full px-4 lg:px-8 py-10",
            div { class: "flex gap-8 xl:gap-12 items-start",

                // ── Note explorer (left edge) ─────────────────
                nav { class: "hidden lg:block w-56 shrink-0 sticky top-24",
                    div { class: "text-xs uppercase tracking-wider text-muted-foreground mb-2", "Guides vault" }
                    VaultExplorer { notes: notes.clone(), current: current_path.clone() }
                }

                // ── The note (centered in the wide middle) ────
                div { class: "flex-1 min-w-0 flex justify-center",
                    div { class: "w-full max-w-7xl min-w-0",
                        if let Some(note) = current.as_ref() {
                            div { class: "mb-4", NoteChips { content: note.content.clone() } }
                            for (i , seg) in segments.iter().enumerate() {
                                {
                                    match seg {
                                        Segment::Md(text) => rsx! {
                                            MdSegment {
                                                key: "{i}",
                                                content: text.clone(),
                                                decorations: decorations.clone(),
                                                on_link_click,
                                            }
                                        },
                                        Segment::Cast { name, side_md, media_right } => rsx! {
                                            ScreencastBlock {
                                                key: "{i}",
                                                name: name.clone(),
                                                side_md: side_md.clone(),
                                                media_right: *media_right,
                                                decorations: decorations.clone(),
                                                on_link_click,
                                            }
                                        },
                                    }
                                }
                            }
                        } else {
                            div { class: "py-16 text-center",
                                p { class: "text-muted-foreground mb-4", "That note doesn't exist in the guides vault." }
                                Link { to: Route::GuidesPage {}, class: "text-primary hover:underline", "Back to the guides" }
                            }
                        }
                    }
                }

                // ── Connections graph (far right edge) ────────
                aside { class: "hidden xl:block w-72 2xl:w-80 shrink-0 sticky top-24",
                    div { class: "text-xs uppercase tracking-wider text-muted-foreground mb-2", "Connections" }
                    div { class: "rounded-xl border border-border/60 bg-card/40 overflow-hidden h-80",
                        KnowledgeGraphView {
                            graph,
                            active: current_stem.clone(),
                            on_node_click,
                        }
                    }
                    if !title.is_empty() {
                        p { class: "mt-2 text-[0.65rem] text-muted-foreground",
                            "Click a node to open its note \u{00b7} drag to pan \u{00b7} scroll to zoom. Current: {title}."
                        }
                    }
                }
            }
        }
    }
}

/// One markdown run of a note, rendered in its own read-only editor
/// (reseeded when its content changes). Reading mode hides every source
/// marker regardless of caret.
#[component]
fn MdSegment(
    content: String,
    decorations: DecorationSource,
    on_link_click: Callback<String>,
) -> Element {
    let mut state = use_signal(|| EditorState::new(String::new()));
    use_effect(use_reactive!(|(content,)| {
        if state.peek().doc.to_string() != content {
            let mut s = EditorState::new(content.clone());
            s.reading_mode = true;
            state.set(s);
        }
    }));
    rsx! {
        Editor { state, decorations: decorations.clone(), editable: false, on_link_click }
    }
}

/// A screencast block: the 16:9 media beside a notes column that fills
/// the width (caption, bullets, `kbd:@` refs, `[[links]]` — all rendered
/// as markdown). `media_right` flips the pair so the text sits on the
/// left and the media on the right; otherwise media-left. Stacks
/// vertically on narrow screens. The media falls back to the animated
/// placeholder until a real recording exists under its name.
#[component]
fn ScreencastBlock(
    name: String,
    side_md: String,
    #[props(default)] media_right: bool,
    decorations: DecorationSource,
    on_link_click: Callback<String>,
) -> Element {
    let media = media_render(&name);
    // Media and notes are always in the same DOM order; on desktop we
    // reverse the row to put the media on the right when asked.
    let row = if media_right { "lg:flex-row-reverse" } else { "lg:flex-row" };
    rsx! {
        div { class: "cast-block flex flex-col {row} gap-6 items-start my-7",
            // ── 16:9 media (left) ─────────────────────────
            div { class: "cast-media w-full lg:w-[34rem] xl:w-[38rem] shrink-0",
                {
                    match media {
                        Some((url, true)) => rsx! {
                            video { class: "cast-frame", src: "{url}", autoplay: true, muted: true, r#loop: true }
                        },
                        Some((url, false)) => rsx! {
                            img { class: "cast-frame", src: "{url}", alt: "{name}" }
                        },
                        None => rsx! {},
                    }
                }
            }
            // ── notes column (fills the width, right) ─────
            if !side_md.trim().is_empty() {
                div { class: "cast-notes flex-1 min-w-0 lg:pt-1",
                    MdSegment { content: side_md.clone(), decorations: decorations.clone(), on_link_click }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Explorer
// ---------------------------------------------------------------------------

/// Folder tree from the vault paths: root notes, then one section per
/// directory (folder note first, then its children by title).
#[component]
fn VaultExplorer(notes: Vec<VaultNote>, current: String) -> Element {
    let mut roots: Vec<&VaultNote> = Vec::new();
    let mut dirs: BTreeMap<String, Vec<&VaultNote>> = BTreeMap::new();
    for n in &notes {
        match n.path.split_once('/') {
            Some((dir, _)) => dirs.entry(dir.to_string()).or_default().push(n),
            None => roots.push(n),
        }
    }
    roots.sort_by_key(|n| n.title().to_lowercase());
    for children in dirs.values_mut() {
        // Folder note first, then by title.
        children.sort_by_key(|n| {
            let is_folder_note = n
                .path
                .strip_suffix(".md")
                .is_some_and(|p| p.split('/').rev().take(2).collect::<Vec<_>>().windows(2).all(|w| w[0] == w[1]) && p.contains('/'));
            (!is_folder_note, n.title().to_lowercase())
        });
    }

    rsx! {
        div { class: "flex flex-col gap-0.5",
            for n in roots {
                ExplorerRow { path: n.path.clone(), title: n.title(), depth: 0, current: current.clone(), folder: false }
            }
            for (dir, children) in dirs.iter() {
                div { key: "{dir}", class: "mt-1",
                    div { class: "flex items-center gap-1.5 px-2 py-1 text-xs uppercase tracking-wider text-muted-foreground/70",
                        Folder { class: "w-3.5 h-3.5" }
                        "{dir}"
                    }
                    for n in children.iter() {
                        ExplorerRow { path: n.path.clone(), title: n.title(), depth: 1, current: current.clone(), folder: false }
                    }
                }
            }
        }
    }
}

#[component]
fn ExplorerRow(path: String, title: String, depth: usize, current: String, folder: bool) -> Element {
    let active = path == current;
    let indent = depth * 12 + 8;
    rsx! {
        Link {
            to: note_route(&path),
            class: if active {
                "flex items-center gap-1.5 rounded px-2 py-1 text-sm bg-accent/60 text-foreground"
            } else {
                "flex items-center gap-1.5 rounded px-2 py-1 text-sm text-muted-foreground hover:text-foreground hover:bg-accent/30 transition-colors"
            },
            style: "padding-left: {indent}px;",
            FileText { class: "w-3.5 h-3.5 shrink-0 opacity-60" }
            span { class: "min-w-0 truncate", "{title}" }
        }
    }
}

// ---------------------------------------------------------------------------
// Tests — the vault can't silently drift from the input configs.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use input_config_proto::{SectionConfig, WhichKeyEntryDef};

    use super::*;
    use crate::components::input_tutorial::embedded::PROFILES;

    #[test]
    fn vault_embeds_and_parses() {
        let notes = embedded_vault();
        assert!(notes.len() >= 6, "guides vault lost notes");
        for n in &notes {
            assert!(!n.title().is_empty(), "{} has no title", n.path);
        }
        // The landing + reaper folder notes exist for the routes.
        assert!(resolve_route(&notes, &[]).is_some(), "vault index note missing");
        assert!(
            resolve_route(&notes, &["reaper".into()]).is_some(),
            "reaper folder note missing"
        );
        assert!(
            resolve_route(&notes, &["reaper".into(), "transport".into()]).is_some(),
            "URL compat: /guides/reaper/transport must resolve"
        );
    }

    /// The ported Keyflow guide: folder note + 10 chapters, sane
    /// frontmatter conversion (title, kind: concept, numeric order
    /// from the docs-site weights), and its ```kf fences intact.
    #[test]
    fn keyflow_guide_ported() {
        let notes = embedded_vault();
        let keyflow: Vec<&VaultNote> = notes
            .iter()
            .filter(|n| n.path.starts_with("keyflow/"))
            .collect();
        assert_eq!(keyflow.len(), 11, "keyflow guide should be 11 notes");

        assert!(
            resolve_route(&notes, &["keyflow".into()]).is_some(),
            "keyflow folder note missing"
        );
        assert!(
            resolve_route(&notes, &["keyflow".into(), "chords".into()]).is_some(),
            "/guides/keyflow/chords must resolve"
        );

        let mut orders = Vec::new();
        for n in &keyflow {
            assert_eq!(
                fm_field(&n.content, "kind").as_deref(),
                Some("concept"),
                "{}: keyflow notes are concept notes",
                n.path
            );
            let order: u32 = fm_field(&n.content, "order")
                .unwrap_or_else(|| panic!("{}: missing order", n.path))
                .parse()
                .unwrap_or_else(|_| panic!("{}: non-numeric order", n.path));
            orders.push(order);
        }
        orders.sort_unstable();
        assert_eq!(
            orders,
            (0..=10).collect::<Vec<u32>>(),
            "chapter order should be the contiguous docs-site weights"
        );

        // The engraved-chart fences survived the conversion.
        let chords = keyflow
            .iter()
            .find(|n| n.path == "keyflow/chords.md")
            .expect("chords chapter");
        assert!(
            chords.content.contains("```kf+\nCmaj7 | F#m7b5 | Bbmaj9 | G7b9\n```"),
            "chords chapter lost its kf+ fence (source + chart together)"
        );
    }

    #[test]
    fn every_wikilink_resolves() {
        let notes = embedded_vault();
        for n in &notes {
            for target in view_knowledge_graph::parse::extract_wikilinks(&n.content) {
                assert!(
                    resolve_note(&notes, &target).is_some(),
                    "{}: wikilink [[{target}]] resolves to no note",
                    n.path
                );
            }
        }
    }

    #[test]
    fn note_routes_round_trip() {
        let notes = embedded_vault();
        for n in &notes {
            let segs = match note_route(&n.path) {
                Route::GuidesPage {} => Vec::new(),
                Route::GuideNotePage { path } => path,
                r => panic!("unexpected route {r:?} for {}", n.path),
            };
            let resolved = resolve_route(&notes, &segs)
                .unwrap_or_else(|| panic!("route for {} resolves to nothing", n.path));
            assert_eq!(resolved.path, n.path, "route round-trip mismatch");
        }
    }

    /// Inline code spans of a markdown body (fenced blocks skipped).
    fn code_spans(md: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut in_fence = false;
        for line in md.lines() {
            if line.trim_start().starts_with("```") {
                in_fence = !in_fence;
                continue;
            }
            if in_fence {
                continue;
            }
            let mut rest = line;
            while let Some(start) = rest.find('`') {
                let after = &rest[start + 1..];
                let Some(end) = after.find('`') else { break };
                out.push(after[..end].to_string());
                rest = &after[end + 1..];
            }
        }
        out
    }

    /// Does a code span read as a key sequence (`r`, `<C-s>`, `n d`,
    /// `<S-n> s a`)? Multi-char bare words (action ids, commands)
    /// don't.
    fn looks_like_keys(span: &str) -> bool {
        let mut tokens = span.split_whitespace().peekable();
        if tokens.peek().is_none() {
            return false;
        }
        tokens.all(|t| t.chars().count() == 1 || (t.starts_with('<') && t.ends_with('>')))
    }

    /// Every leaf AND branch sequence of a which-key tree, plus the
    /// prefix itself (guides legitimately reference bare prefixes).
    fn walk(prefix: &str, entries: &[WhichKeyEntryDef], out: &mut HashSet<String>) {
        out.insert(prefix.to_string());
        for e in entries {
            let seq = format!("{prefix} {}", e.key);
            out.insert(seq.clone());
            if let Some(children) = &e.children {
                walk(&seq, children, out);
            }
        }
    }

    /// Drift guard, two halves:
    ///
    /// - every `kbd:@action` ref anywhere in the vault must resolve
    ///   through [`SiteKbdIndex`] (base profile + which-key leaves +
    ///   mode layers) — an unresolved ref means the guide points at
    ///   an action nothing is bound to;
    /// - every key-LITERAL shortcut (`kbd:<C-s>`, `kbd:n d`, or a
    ///   bare key-looking code span) in a `kind: input` note must
    ///   exist in the fasttrackstudio profile (bindings + which-key
    ///   sequences/prefixes) or the note's declared `mode:` layer.
    #[test]
    fn input_note_shortcuts_exist_in_configs() {
        use editor::markdown::KbdLookup as _;

        let profile = PROFILES
            .iter()
            .find(|p| p.id == "fasttrackstudio")
            .expect("fasttrackstudio profile embedded");

        let mut base: HashSet<String> = HashSet::new();
        for s in profile.sections {
            let config: SectionConfig = match facet_styx::from_str(s.styx) {
                Ok(c) => c,
                Err(_) => continue,
            };
            for b in config.bindings() {
                base.insert(b.keys.clone());
            }
            for tree in config.which_key() {
                walk(&tree.prefix, &tree.entries, &mut base);
            }
        }
        assert!(!base.is_empty(), "profile produced no key sequences");

        let kbd_index = SiteKbdIndex::build();

        let mut refs_checked = 0;
        let mut literals_checked = 0;
        let mut mode_checked = 0;
        for note in embedded_vault() {
            let is_input = fm_field(&note.content, "kind").as_deref() == Some("input");
            let mode_keys: HashSet<String> = fm_field(&note.content, "mode")
                .map(|mid| {
                    let m = crate::components::modes::find_mode(&mid).unwrap_or_else(|| {
                        panic!("{}: unknown mode {mid:?} in frontmatter", note.path)
                    });
                    m.bindings.iter().map(|b| b.keys.clone()).collect()
                })
                .unwrap_or_default();

            for span in code_spans(&note.content) {
                // Action refs must resolve in EVERY note.
                if let Some(action) = span.strip_prefix("kbd:@") {
                    refs_checked += 1;
                    assert!(
                        kbd_index.keys_for_action(action.trim()).is_some(),
                        "{}: `kbd:@{action}` resolves to no binding in the \
                         fasttrackstudio profile or any mode layer — update \
                         the note or the config",
                        note.path,
                    );
                    continue;
                }
                // Literals only guard input notes.
                if !is_input {
                    continue;
                }
                let literal = span.strip_prefix("kbd:").unwrap_or(&span).trim().to_string();
                if !looks_like_keys(&literal) {
                    continue;
                }
                literals_checked += 1;
                if mode_keys.contains(&literal) {
                    mode_checked += 1;
                    continue;
                }
                assert!(
                    base.contains(&literal),
                    "{}: shortcut `{literal}` does not exist in the fasttrackstudio \
                     profile{} — update the note or the config",
                    note.path,
                    if mode_keys.is_empty() { "" } else { " or its mode's overlays" },
                );
            }
        }
        assert!(refs_checked > 15, "suspiciously few @refs checked ({refs_checked})");
        assert!(
            literals_checked > 3,
            "suspiciously few literals checked ({literals_checked})"
        );
        assert!(mode_checked > 0, "no mode-layered literal was exercised");
    }
}
